import { RendererCanvas } from '../../../lib';

export class Solution {
	public divHost: HTMLElement;
	public renderer: Renderer;
	constructor(id: string) {
		this.divHost = document.getElementById(id);

		this.divHost.style.display = 'flex';
		this.divHost.style.flexDirection = 'column';
		this.divHost.style.alignItems = 'center';
		this.divHost.style.gap = '20px';
		this.divHost.style.padding = '20px';

		const controlPanel = document.createElement('div');
		controlPanel.style.backgroundColor = '#333';
		controlPanel.style.padding = '20px';
		controlPanel.style.borderRadius = '8px';
		controlPanel.style.width = '1000px';
		controlPanel.style.display = 'flex';
		controlPanel.style.gap = '30px';
		controlPanel.style.justifyContent = 'center';

		const widthControl = this.createSlider('Target Width', 300, 800, 600, (value) => {
			this.renderer.widthTarget = value;
			this.renderer.recalculateLayout();
		});

		const heightControl = this.createSlider('Target Height', 300, 800, 500, (value) => {
			this.renderer.lengthTarget = value;
			this.renderer.recalculateLayout();
		});

		controlPanel.appendChild(widthControl);
		controlPanel.appendChild(heightControl);
		this.divHost.appendChild(controlPanel);

		const div = document.createElement('div');
		div.style.backgroundColor = '#555';
		div.style.width = '1000px';
		div.style.height = '700px';
		this.divHost.appendChild(div);

		this.renderer = new Renderer(div);
		this.renderer.start();
	}

	private createSlider(label: string, min: number, max: number, initial: number, onChange: (value: number) => void): HTMLElement {
		const container = document.createElement('div');
		container.style.display = 'flex';
		container.style.flexDirection = 'column';
		container.style.gap = '8px';
		container.style.flex = '1';

		const labelEl = document.createElement('label');
		labelEl.textContent = label;
		labelEl.style.color = '#fff';
		labelEl.style.fontSize = '14px';
		labelEl.style.fontWeight = 'bold';

		const valueDisplay = document.createElement('span');
		valueDisplay.textContent = `${initial}px`;
		valueDisplay.style.color = '#4CAF50';
		valueDisplay.style.fontSize = '16px';
		valueDisplay.style.fontWeight = 'bold';

		const slider = document.createElement('input');
		slider.type = 'range';
		slider.min = min.toString();
		slider.max = max.toString();
		slider.value = initial.toString();
		slider.style.width = '100%';

		slider.addEventListener('input', (e) => {
			const value = parseInt((e.target as HTMLInputElement).value);
			valueDisplay.textContent = `${value}px`;
			onChange(value);
		});

		const topRow = document.createElement('div');
		topRow.style.display = 'flex';
		topRow.style.justifyContent = 'space-between';
		topRow.appendChild(labelEl);
		topRow.appendChild(valueDisplay);

		container.appendChild(topRow);
		container.appendChild(slider);

		return container;
	}

	public destroy() {
		if (this.divHost) {
			try {
				while (this.divHost.firstChild) {
					this.divHost.removeChild(this.divHost.firstChild);
				}
			} catch (error) {
				console.error('Error in destroy method:', error);
			}
		}
	}
}

interface Area {
	name: string;
	width: number;
	length: number;
	color: number;
	priority: number;
	x?: number;
	y?: number;
}

interface LayoutConfig {
	targetWidth: number;
	targetHeight: number;
	loadingEntrance: { x: number; y: number };
	humanEntrance: { x: number; y: number };
}

const areas: Area[] = [
	{ color: 0x333333, width: 85, length: 120, name: 'Loading Zone', priority: 1 },
	{ color: 0x4477aa, width: 212.5, length: 120, name: 'Integration Bay', priority: 2 },
	{ color: 0xe9cb70, width: 84, length: 70, name: 'Finishing Zone', priority: 3 },
	{ color: 0xe1857f, width: 84, length: 70, name: 'Fabrication', priority: 2 },
	{ color: 0xed9e66, width: 84, length: 70, name: 'Hardware', priority: 4 },
	{ color: 0x8c7bf0, width: 84, length: 60, name: 'Network Lab', priority: 5 },
	{ color: 0x44aa77, width: 212.5, length: 45, name: 'Work Desk Zone', priority: 6 },
	{ color: 0xc1d878, width: 90, length: 50, name: 'Ping Pong', priority: 9 },
	{ color: 0xc1d878, width: 90, length: 50, name: 'Wellness', priority: 9 },
	{ color: 0xb19ff3, width: 85, length: 70, name: 'Demo Area', priority: 8 },
	{ color: 0xaa44aa, width: 85, length: 80, name: 'Reception', priority: 10 },
	{ color: 0xaa6644, width: 110, length: 100, name: 'Rest room', priority: 7 },
];

class SpacePlanner {
	private config: LayoutConfig;

	constructor(config: LayoutConfig) {
		this.config = config;
	}

	calculateLayout(inputAreas: Area[]): Area[] {
		// 우선순위와 크기로 정렬
		const sortedAreas = [...inputAreas].sort((a, b) => {
			if (a.priority !== b.priority) return a.priority - b.priority;
			return b.width * b.length - a.width * a.length;
		});

		const placed: Area[] = [];
		const rows: { y: number; height: number; items: Area[] }[] = [];

		let currentY = 0;

		for (const area of sortedAreas) {
			let bestRow = -1;
			let bestX = -1;
			let bestScore = -Infinity;

			// 기존 행에 배치 시도
			for (let r = 0; r < rows.length; r++) {
				const row = rows[r];
				const usedWidth = row.items.reduce((sum, item) => sum + item.width, 0);
				const availableWidth = this.config.targetWidth - usedWidth;

				// 현재 행에 들어갈 수 있는지 확인
				if (availableWidth >= area.width && row.height >= area.length) {
					const centerX = usedWidth + area.width / 2;
					const centerY = row.y + area.length / 2;
					const score = this.calculateScore(centerX, centerY, area.priority);

					if (score > bestScore) {
						bestScore = score;
						bestRow = r;
						bestX = usedWidth;
					}
				}
			}

			// 기존 행에 배치
			if (bestRow !== -1) {
				const row = rows[bestRow];
				placed.push({
					...area,
					x: bestX,
					y: row.y,
				});
				row.items.push(area);
			} else {
				// 새로운 행 생성
				if (currentY + area.length <= this.config.targetHeight) {
					placed.push({
						...area,
						x: 0,
						y: currentY,
					});
					rows.push({
						y: currentY,
						height: area.length,
						items: [area],
					});
					currentY += area.length;
				} else {
					// 공간이 부족하면 기존 행에 강제로 배치 시도
					for (let r = 0; r < rows.length; r++) {
						const row = rows[r];
						const usedWidth = row.items.reduce((sum, item) => sum + item.width, 0);

						if (this.config.targetWidth - usedWidth >= area.width) {
							// 높이를 늘려서라도 배치
							placed.push({
								...area,
								x: usedWidth,
								y: row.y,
							});
							row.items.push(area);
							row.height = Math.max(row.height, area.length);
							break;
						}
					}
				}
			}
		}

		// 빈 공간을 작은 박스로 채우기
		this.fillEmptySpaces(placed, rows);

		return placed;
	}

	private fillEmptySpaces(placed: Area[], rows: { y: number; height: number; items: Area[] }[]) {
		const fillColors = [0x666666, 0x777777, 0x888888, 0x999999];
		let fillIndex = 0;

		// 각 행의 남은 공간 채우기
		rows.forEach((row, rowIdx) => {
			const usedWidth = row.items.reduce((sum, item) => sum + item.width, 0);
			const remainingWidth = this.config.targetWidth - usedWidth;

			if (remainingWidth >= 20) {
				// 남은 공간을 균등하게 나누어 채우기
				const numBoxes = Math.max(1, Math.floor(remainingWidth / 40));
				const boxWidth = remainingWidth / numBoxes;

				for (let i = 0; i < numBoxes; i++) {
					placed.push({
						name: `Fill ${rowIdx}-${i}`,
						width: boxWidth,
						length: row.height,
						color: fillColors[fillIndex % fillColors.length],
						priority: 99,
						x: usedWidth + i * boxWidth,
						y: row.y,
					});
					fillIndex++;
				}
			}
		});

		// 하단 빈 공간 채우기
		const totalUsedHeight = rows.reduce((sum, row) => sum + row.height, 0);
		const remainingHeight = this.config.targetHeight - totalUsedHeight;

		if (remainingHeight >= 20) {
			const numRows = Math.max(1, Math.floor(remainingHeight / 40));
			const rowHeight = remainingHeight / numRows;
			const numCols = Math.max(2, Math.floor(this.config.targetWidth / 80));
			const colWidth = this.config.targetWidth / numCols;

			for (let r = 0; r < numRows; r++) {
				for (let c = 0; c < numCols; c++) {
					placed.push({
						name: `Fill B${r}-${c}`,
						width: colWidth,
						length: rowHeight,
						color: fillColors[fillIndex % fillColors.length],
						priority: 99,
						x: c * colWidth,
						y: totalUsedHeight + r * rowHeight,
					});
					fillIndex++;
				}
			}
		}
	}

	private calculateScore(x: number, y: number, priority: number): number {
		let score = 0;

		if (priority <= 5) {
			const dist = Math.sqrt(Math.pow(x - this.config.loadingEntrance.x, 2) + Math.pow(y - this.config.loadingEntrance.y, 2));
			score -= dist;
		} else {
			const dist = Math.sqrt(Math.pow(x - this.config.humanEntrance.x, 2) + Math.pow(y - this.config.humanEntrance.y, 2));
			score -= dist;
		}

		return score;
	}
}

export class Renderer extends RendererCanvas {
	private finalLayout: Area[] = [];
	private config: LayoutConfig;
	public widthTarget = 600;
	public lengthTarget = 500;

	constructor(div: any) {
		super(div);
		this.canvas.style.position = 'relative';
		this.canvas.style.width = '100%';
		this.canvas.style.height = '100%';

		this.recalculateLayout();
	}

	public recalculateLayout() {
		this.config = {
			targetWidth: this.widthTarget,
			targetHeight: this.lengthTarget,
			loadingEntrance: { x: 0, y: 0 },
			humanEntrance: { x: this.widthTarget, y: this.lengthTarget },
		};

		const planner = new SpacePlanner(this.config);
		this.finalLayout = planner.calculateLayout(areas);

		console.log('최종 배치:', this.finalLayout.length, '개 영역');

		this.isStatic = false;
	}

	public render(ctx: CanvasRenderingContext2D): void {
		ctx.fillStyle = '#1a1a1a';
		ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

		// 타겟 바운더리
		ctx.strokeStyle = '#00ff00';
		ctx.lineWidth = 3;
		ctx.setLineDash([10, 5]);
		ctx.strokeRect(0, 0, this.widthTarget, this.lengthTarget);
		ctx.setLineDash([]);

		// 모든 영역 그리기
		this.finalLayout.forEach((area) => {
			if (area.x !== undefined && area.y !== undefined) {
				ctx.fillStyle = this.colorToHex(area.color);
				ctx.fillRect(area.x, area.y, area.width, area.length);

				ctx.strokeStyle = area.priority === 99 ? '#444444' : '#ffffff';
				ctx.lineWidth = area.priority === 99 ? 1 : 2;
				ctx.strokeRect(area.x, area.y, area.width, area.length);

				// Fill 영역이 아닌 경우만 텍스트 표시
				if (area.priority !== 99) {
					ctx.fillStyle = '#ffffff';
					ctx.font = 'bold 11px Arial';
					ctx.textAlign = 'center';
					ctx.textBaseline = 'middle';

					const centerX = area.x + area.width / 2;
					const centerY = area.y + area.length / 2;

					const words = area.name.split(' ');
					if (words.length > 1 && area.width < 100) {
						words.forEach((word, i) => {
							ctx.fillText(word, centerX, centerY - 10 + i * 14);
						});
					} else {
						ctx.fillText(area.name, centerX, centerY - 7);
					}

					ctx.font = '9px Arial';
					ctx.fillText(`${Math.round(area.width)} × ${Math.round(area.length)}`, centerX, centerY + 8);
				}
			}
		});

		// 출입구 표시
		this.drawEntrance(ctx, this.config.loadingEntrance, 'LOADING', '#ff4444');
		this.drawEntrance(ctx, this.config.humanEntrance, 'ENTRANCE', '#44ff44');

		// 통계
		const mainAreas = this.finalLayout.filter((a) => a.priority !== 99).length;
		const fillAreas = this.finalLayout.filter((a) => a.priority === 99).length;
		const utilization = this.calculateUtilization();

		ctx.fillStyle = '#ffffff';
		ctx.font = 'bold 12px Arial';
		ctx.textAlign = 'left';
		ctx.fillText(`Target: ${this.widthTarget} × ${this.lengthTarget}px`, 10, this.lengthTarget + 30);
		ctx.fillText(`Main Areas: ${mainAreas} | Fill Boxes: ${fillAreas}`, 10, this.lengthTarget + 50);
		ctx.fillText(`Utilization: ${utilization.toFixed(1)}%`, 10, this.lengthTarget + 70);

		this.isStatic = false;
	}

	private drawEntrance(ctx: CanvasRenderingContext2D, pos: { x: number; y: number }, label: string, color: string): void {
		ctx.fillStyle = color;
		ctx.beginPath();
		ctx.arc(pos.x, pos.y, 10, 0, Math.PI * 2);
		ctx.fill();

		ctx.strokeStyle = '#ffffff';
		ctx.lineWidth = 2;
		ctx.stroke();

		ctx.fillStyle = color;
		ctx.font = 'bold 12px Arial';
		ctx.textAlign = 'center';
		ctx.textBaseline = 'bottom';
		ctx.fillText(label, pos.x, pos.y - 15);
	}

	private calculateUtilization(): number {
		const totalArea = this.finalLayout.reduce((sum, a) => sum + a.width * a.length, 0);
		const targetArea = this.widthTarget * this.lengthTarget;
		return targetArea > 0 ? (totalArea / targetArea) * 100 : 0;
	}

	private colorToHex(color: number): string {
		return '#' + color.toString(16).padStart(6, '0');
	}
}
